//! 📨️ Authored scalar metadata parses original borrowed JSON with no replacement heap owner.
use super::*;
use semio_framework_value::NativeEncodeControl;
#[derive(Clone,Copy)]
pub(super) enum MetadataKind { Retirement,Close(RetainedCloneGrant) }
pub(super) struct Metadata { pub retirement:sqlite_wire::SnapshotRetirement,pub progress:RetainedCloneProgress,pub refusal:u32 }
struct Parser<'a>{bytes:&'a[u8],at:usize}
impl<'a> Parser<'a>{
 fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"snapshot scalar metadata violates its closed authored schema")}
 fn spaces(&mut self,c:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{let start=self.at;while self.bytes.get(self.at).is_some_and(u8::is_ascii_whitespace){self.at+=1;}c.advance(self.at-start)}
 fn token(&mut self,c:&mut NativeEncodeControl<'_>,token:&[u8])->Result<(),ValueError>{self.spaces(c)?;let end=self.at.checked_add(token.len()).ok_or_else(Self::invalid)?;if self.bytes.get(self.at..end)!=Some(token){return Err(Self::invalid())}c.advance(token.len())?;self.at=end;Ok(())}
 fn key(&mut self,c:&mut NativeEncodeControl<'_>)->Result<&'a[u8],ValueError>{self.token(c,b"\"")?;let start=self.at;while let Some(byte)=self.bytes.get(self.at){if *byte==b'"'{let key=&self.bytes[start..self.at];c.advance(self.at-start)?;self.token(c,b"\"")?;self.token(c,b":")?;return Ok(key)}if *byte<0x20||*byte==b'\\'{return Err(Self::invalid())}self.at+=1;}Err(Self::invalid())}
 fn field(&mut self,c:&mut NativeEncodeControl<'_>,first:&mut bool)->Result<Option<&'a[u8]>,ValueError>{self.spaces(c)?;if self.bytes.get(self.at)==Some(&b'}'){self.token(c,b"}")?;return Ok(None)}if !*first{self.token(c,b",")?;}*first=false;self.key(c).map(Some)}
 fn number(&mut self,c:&mut NativeEncodeControl<'_>)->Result<u64,ValueError>{self.spaces(c)?;let start=self.at;let mut value=0u64;while let Some(byte)=self.bytes.get(self.at).copied().filter(u8::is_ascii_digit){if self.at>start&&self.bytes[start]==b'0'{return Err(Self::invalid())}value=value.checked_mul(10).and_then(|value|value.checked_add((byte-b'0')as u64)).ok_or_else(Self::invalid)?;c.advance(1)?;self.at+=1;}if self.at==start{Err(Self::invalid())}else{Ok(value)}}
 fn boolean(&mut self,c:&mut NativeEncodeControl<'_>)->Result<bool,ValueError>{self.spaces(c)?;if self.bytes.get(self.at)==Some(&b't'){self.token(c,b"true")?;Ok(true)}else{self.token(c,b"false")?;Ok(false)}}
 fn demands(&mut self,c:&mut NativeEncodeControl<'_>)->Result<sqlite_wire::SnapshotDemands,ValueError>{self.token(c,b"{")?;let(mut first,mut mask,mut value)=(true,0u8,sqlite_wire::SnapshotDemands::default());while let Some(key)=self.field(c,&mut first)?{let bit=match key{b"items"=>1,b"copy_bytes"=>2,b"capacity_bytes"=>4,b"release_bytes"=>8,b"depth"=>16,_=>return Err(Self::invalid())};if mask&bit!=0{return Err(Self::invalid())}mask|=bit;let n=self.number(c)?;match bit{1=>value.items=n,2=>value.copy_bytes=n,4=>value.capacity_bytes=n,8=>value.release_bytes=n,16=>value.depth=n,_=>unreachable!()}}if mask!=31{return Err(Self::invalid())}Ok(value)}
 fn retirement(&mut self,c:&mut NativeEncodeControl<'_>)->Result<sqlite_wire::SnapshotRetirement,ValueError>{self.token(c,b"{")?;let(mut first,mut mask,mut value)=(true,0u8,sqlite_wire::SnapshotRetirement::default());while let Some(key)=self.field(c,&mut first)?{let bit=match key{b"ticket"=>1,b"owned_bytes"=>2,b"refusal"=>4,b"native_pending"=>8,b"output_pending"=>16,b"terminal"=>32,b"demands"=>64,_=>return Err(Self::invalid())};if mask&bit!=0{return Err(Self::invalid())}mask|=bit;match bit{1=>value.ticket=self.number(c)?,2=>value.owned_bytes=self.number(c)?,4=>value.refusal=u32::try_from(self.number(c)?).map_err(|_|Self::invalid())?,8=>value.native_pending=self.boolean(c)?,16=>value.output_pending=self.boolean(c)?,32=>value.terminal=self.boolean(c)?,64=>value.demands=self.demands(c)?,_=>unreachable!()}}if mask!=127{return Err(Self::invalid())}Ok(value)}
 fn progress(&mut self,c:&mut NativeEncodeControl<'_>)->Result<sqlite_wire::SnapshotProgress,ValueError>{self.token(c,b"{")?;let(mut first,mut mask,mut value)=(true,0u8,sqlite_wire::SnapshotProgress::default());while let Some(key)=self.field(c,&mut first)?{let bit=match key{b"copied_items"=>1,b"copied_bytes"=>2,b"retained_capacity_bytes"=>4,b"released_bytes"=>8,_=>return Err(Self::invalid())};if mask&bit!=0{return Err(Self::invalid())}mask|=bit;let n=self.number(c)?;match bit{1=>value.copied_items=n,2=>value.copied_bytes=n,4=>value.retained_capacity_bytes=n,8=>value.released_bytes=n,_=>unreachable!()}}if mask!=15{return Err(Self::invalid())}Ok(value)}
 fn close(&mut self,c:&mut NativeEncodeControl<'_>,grant:RetainedCloneGrant)->Result<Metadata,ValueError>{self.token(c,b"{")?;let(mut first,mut mask)=(true,0u8);let mut retirement=None;let mut progress=None;let mut refusal=0;while let Some(key)=self.field(c,&mut first)?{let bit=match key{b"retirement"=>1,b"progress"=>2,b"refusal"=>4,_=>return Err(Self::invalid())};if mask&bit!=0{return Err(Self::invalid())}mask|=bit;match bit{1=>retirement=Some(self.retirement(c)?),2=>progress=Some(self.progress(c)?.native(grant)?),4=>refusal=u32::try_from(self.number(c)?).map_err(|_|Self::invalid())?,_=>unreachable!()}}if mask!=7{return Err(Self::invalid())}Ok(Metadata{retirement:retirement.unwrap(),progress:progress.unwrap(),refusal})}
}
pub(super) fn parse(bytes:&[u8],kind:MetadataKind,control:&mut NativeEncodeControl<'_>)->Result<Metadata,ValueError>{control.scoped_stage(|control|{control.begin_stage(bytes.len())?;let mut parser=Parser{bytes,at:0};parser.token(control,b"{")?;if parser.key(control)?!=b"Ok"{return Err(Parser::invalid())}let value=match kind{MetadataKind::Retirement=>Metadata{retirement:parser.retirement(control)?,progress:Default::default(),refusal:0},MetadataKind::Close(grant)=>parser.close(control,grant)?};parser.token(control,b"}")?;parser.spaces(control)?;if parser.at!=bytes.len(){return Err(Parser::invalid())}control.checkpoint()?;Ok(value)})}

#[cfg(test)]
mod tests {
 use super::*;
 #[test]
 fn original_snapshot_scalar_metadata_borrows_actual_json_without_heap(){
  let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/🪶️sqlite/🧫️fixtures/📨️metadata/🔣️.json")).unwrap();let (_,proof)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(vec![0u8;13]));assert_eq!((proof.requested_bytes,proof.released_bytes),(13,13));let query=serde_json::to_vec(&law["query"]).unwrap();let close=serde_json::to_vec(&law["close"]).unwrap();let mut observer=|_:Progress|true;let mut control=NativeEncodeControl::new(0,&mut observer);let (value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parse(&query,MetadataKind::Retirement,&mut control));let value=value.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let expected:sqlite_wire::SnapshotRetirement=serde_json::from_value(law["query"]["Ok"].clone()).unwrap();assert_eq!(serde_json::to_value(value.retirement).unwrap(),serde_json::to_value(expected).unwrap());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32,maximum_capacity_bytes:64,maximum_release_bytes:16,maximum_depth:4};let (value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parse(&close,MetadataKind::Close(grant),&mut control));let value=value.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let expected:sqlite_wire::SnapshotCloseReceipt=serde_json::from_value(law["close"]["Ok"].clone()).unwrap();assert_eq!(value.progress,expected.progress.native(grant).unwrap());for key in ["duplicate","overflow"]{let (value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parse(law[key].as_str().unwrap().as_bytes(),MetadataKind::Retirement,&mut control));assert_eq!(value.err().unwrap().kind,ValueRefusalKind::InvalidValue);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}assert_eq!(control.owned_bytes(),0);eprintln!("[DEBUG] original borrowed metadata parses real serde query/close, rejects duplicate/overflow, real heap birth/release0 with native maximum0");
 }
 #[test]
 fn original_snapshot_scalar_metadata_cancellation_keeps_source_and_ceiling(){
  let source=br#"{"Ok":{"ticket":9,"owned_bytes":128,"refusal":0,"native_pending":true,"output_pending":false,"terminal":false,"demands":{"items":1,"copy_bytes":64,"capacity_bytes":256,"release_bytes":32,"depth":4}}}"#;let calls=std::cell::Cell::new(0);let mut observer=|_:Progress|{calls.set(calls.get()+1);calls.get()<2};let mut control=NativeEncodeControl::new(0,&mut observer);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||parse(source,MetadataKind::Retirement,&mut control));assert_eq!(result.err().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(control.maximum_bytes(),0);assert_eq!(control.owned_bytes(),0);assert_eq!(source[0],b'{');eprintln!("[DEBUG] same original scalar source remains borrowed on actual cancellation under original maximum0");
 }
}
